  fact_id, claim_text, topics, source_type, source_url_or_document, source_ref, jurisdiction, numbers, volatility, trust_tier, high_risk, reviewer, verified_at, effective_from, expiry_or_review_at, review_cadence_days, approved_languages, status, notes
) values
  ('MB-F1', 'A Cyprus company moves through ten stages: idea, incorporation, banking, tax, accounting, operations, growth, changes, renewal, closure.', array['company-lifecycle']::text[], 'mb-manual', 'newplan/Master Brain & Operating Rules Manual - REFAL AI.txt', 'MB 2.1 / SOURCE-ANALYSIS 6.2', 'CY', '[]'::jsonb, 'STABLE', 'explanatory', false, 'BOSS', '2026-10-07'::date, null, '2027-10-07'::date, 365, array['ar', 'en', 'el']::text[], 'pending', ''),   -- MB-F1
  ('MB-F2', 'The Refalco formation package includes incorporation of a Cyprus Ltd through the full official procedures, usually completed in about two weeks once the customer''s documents are complete.', array['formation-package']::text[], 'refalco-commercial', 'newplan/Master Brain & Operating Rules Manual - REFAL AI.txt', 'MB 2.1 / SOURCE-ANALYSIS 6.3', 'CY', '[{"value":"about two weeks","kind":"duration"}]'::jsonb, 'VOLATILE', 'commercial', true, 'BOSS', '2026-10-07'::date, null, '2026-11-06'::date, 30, array['ar', 'en', 'el']::text[], 'pending', ''),   -- MB-F2 [high risk]
  ('MB-F3', 'The formation package includes reserving the company name and obtaining its approval from the Cyprus Registrar of Companies, which is the step that formally starts the commercial identity.', array['formation-package']::text[], 'refalco-commercial', 'newplan/Master Brain & Operating Rules Manual - REFAL AI.txt', 'MB 2.1 / SOURCE-ANALYSIS 6.3', 'CY', '[]'::jsonb, 'VOLATILE', 'commercial', false, 'BOSS', '2026-10-07'::date, null, '2026-11-06'::date, 30, array['ar', 'en', 'el']::text[], 'pending', ''),   -- MB-F3
  ('MB-F4', 'The formation package includes preparing and attesting the incorporation documents, drafting the Memorandum and Articles of Association and filing them so the file is not rejected administratively.', array['formation-package']::text[], 'refalco-commercial', 'newplan/Master Brain & Operating Rules Manual - REFAL AI.txt', 'MB 2.1 / SOURCE-ANALYSIS 6.3', 'CY', '[]'::jsonb, 'VOLATILE', 'commercial', false, 'BOSS', '2026-10-07'::date, null, '2026-11-06'::date, 30, array['ar', 'en', 'el']::text[], 'pending', ''),   -- MB-F4
  ('MB-F5', 'The formation package includes issuance of the Certificate of Incorporation and the official company certificates, which are the core documents for opening accounts and signing contracts.', array['formation-package']::text[], 'refalco-commercial', 'newplan/Master Brain & Operating Rules Manual - REFAL AI.txt', 'MB 2.1 / SOURCE-ANALYSIS 6.3', 'CY', '[]'::jsonb, 'VOLATILE', 'commercial', false, 'BOSS', '2026-10-07'::date, null, '2026-11-06'::date, 30, array['ar', 'en', 'el']::text[], 'pending', ''),   -- MB-F5
  ('MB-F6', 'The formation package includes the Company Secretary for 4 consecutive months. The Company Secretary is a statutory corporate function required of a Cyprus company, not a personal assistant.', array['formation-package']::text[], 'refalco-commercial', 'newplan/Master Brain & Operating Rules Manual - REFAL AI.txt', 'MB 2.1 / SOURCE-ANALYSIS 6.3', 'CY', '[{"value":"4 months","kind":"duration"}]'::jsonb, 'VOLATILE', 'commercial', true, 'BOSS', '2026-10-07'::date, null, '2026-11-06'::date, 30, array['ar', 'en', 'el']::text[], 'pending', ''),   -- MB-F6 [high risk]
  ('MB-F7', 'The formation package includes the Registered Address for 4 consecutive months. It is the company''s official address in Cyprus for correspondence, not a private office or an apartment.', array['formation-package']::text[], 'refalco-commercial', 'newplan/Master Brain & Operating Rules Manual - REFAL AI.txt', 'MB 2.1 / SOURCE-ANALYSIS 6.3', 'CY', '[{"value":"4 months","kind":"duration"}]'::jsonb, 'VOLATILE', 'commercial', true, 'BOSS', '2026-10-07'::date, null, '2026-11-06'::date, 30, array['ar', 'en', 'el']::text[], 'pending', ''),   -- MB-F7 [high risk]
  ('MB-F8', 'The formation package is managed remotely, so the early procedures are completed without the customer travelling to Cyprus.', array['formation-package']::text[], 'refalco-commercial', 'newplan/Master Brain & Operating Rules Manual - REFAL AI.txt', 'MB 2.1 / SOURCE-ANALYSIS 6.3', 'CY', '[]'::jsonb, 'VOLATILE', 'commercial', false, 'BOSS', '2026-10-07'::date, null, '2026-11-06'::date, 30, array['ar', 'en', 'el']::text[], 'pending', ''),   -- MB-F8
  ('MB-F9', 'The Cyprus formation package is sold at a single headline price plus VAT, and REFAL states that price only as it is currently published in the live offers table, never from memory and never as an estimate.', array['formation-package']::text[], 'refalco-commercial', 'newplan/Master Brain & Operating Rules Manual - REFAL AI.txt', 'MB 2.1 / SOURCE-ANALYSIS 6.3', 'CY', '[]'::jsonb, 'VOLATILE', 'commercial', true, 'BOSS', '2026-10-07'::date, null, '2026-11-06'::date, 30, array['ar', 'en', 'el']::text[], 'pending', 'The figure itself lives in refal_offers_and_pricing (MB-DYN6) and is deliberately absent from this row.'),   -- MB-F9 [high risk]
  ('MB-F10', 'When the customer represents a large commercial entity or an existing international company, REFAL does not assume a new Ltd is needed and instead explains Branch and Subsidiary as corporate advisory options.', array['company-structures']::text[], 'mb-manual', 'newplan/Master Brain & Operating Rules Manual - REFAL AI.txt', 'MB 2.1 / SOURCE-ANALYSIS 6.4', 'CY', '[]'::jsonb, 'STABLE', 'explanatory', false, 'BOSS', '2026-10-07'::date, null, '2027-10-07'::date, 365, array['ar', 'en', 'el']::text[], 'pending', ''),   -- MB-F10
  ('MB-F11', 'A shareholder is the owner of the company''s shares and capital.', array['shareholder-vs-director']::text[], 'mb-manual', 'newplan/Master Brain & Operating Rules Manual - REFAL AI.txt', 'MB 2.1 / SOURCE-ANALYSIS 6.4', 'CY', '[]'::jsonb, 'STABLE', 'explanatory', false, 'BOSS', '2026-10-07'::date, null, '2027-10-07'::date, 365, array['ar', 'en', 'el']::text[], 'pending', ''),   -- MB-F11
  ('MB-F12', 'A director is the executive, administrative and legal officer who manages the company.', array['shareholder-vs-director']::text[], 'mb-manual', 'newplan/Master Brain & Operating Rules Manual - REFAL AI.txt', 'MB 2.1 / SOURCE-ANALYSIS 6.4', 'CY', '[]'::jsonb, 'STABLE', 'explanatory', false, 'BOSS', '2026-10-07'::date, null, '2027-10-07'::date, 365, array['ar', 'en', 'el']::text[], 'pending', ''),   -- MB-F12
  ('MB-F13', 'REFAL puts it simply for the customer: the shareholder is the owner and the director is the person who runs the company, and the same person can be both depending on the structure.', array['shareholder-vs-director']::text[], 'mb-manual', 'newplan/Master Brain & Operating Rules Manual - REFAL AI.txt', 'MB 2.1 / SOURCE-ANALYSIS 6.4', 'CY', '[]'::jsonb, 'STABLE', 'explanatory', false, 'BOSS', '2026-10-07'::date, null, '2027-10-07'::date, 365, array['ar', 'en', 'el']::text[], 'pending', ''),   -- MB-F13
  ('MB-F14', 'A change of company directors or secretary is notified to the Cyprus Registrar using form HE4. A filing for an ownership or shareholding change must be checked against the applicable procedure and company documents.', array['ownership-changes']::text[], 'cy-authority', 'https://www.companies.gov.cy/en/knowledgebase/forms-fees/companies-forms-and-fees/285/form-updating-directors-and-secretary', 'Cyprus Registrar, Form updating directors and secretary (HE4), https://www.companies.gov.cy/en/knowledgebase/forms-fees/companies-forms-and-fees/285/form-updating-directors-and-secretary (checked 2026-10-11); shareholding changes require separate procedure review', 'CY', '[]'::jsonb, 'STABLE', 'regulated', false, 'BOSS', '2026-10-11'::date, null, '2027-04-09'::date, 180, array['ar', 'en', 'el']::text[], 'pending', 'HE4 covers notification of changes to directors, secretary, or their particulars. It does not establish that every shareholding or partner change is simple; check the applicable filing and the company''s governing documents. Verified against the Registrar source on 2026-10-11.'),   -- MB-F14
  ('MB-F15', 'The registered address included for 4 months is an administrative requirement, not workspace. A customer who needs desks, meeting rooms, mail handling or real commercial presence is handled as a physical or virtual office requirement.', array['registered-vs-physical-office']::text[], 'mb-manual', 'newplan/Master Brain & Operating Rules Manual - REFAL AI.txt', 'MB 2.1 / SOURCE-ANALYSIS 6.4', 'CY', '[{"value":"4 months","kind":"duration"}]'::jsonb, 'VOLATILE', 'explanatory', false, 'BOSS', '2026-10-07'::date, null, '2026-11-06'::date, 30, array['ar', 'en', 'el']::text[], 'pending', 'Override: topic is STABLE, but the 4 month term is a commercial package term that can change.'),   -- MB-F15
  ('MB-F16', 'Legitimate structural privacy is not the same as concealing the Ultimate Beneficial Owner to evade costs or controls, and REFAL states clearly that illegal concealment is not supported.', array['privacy-vs-concealment']::text[], 'mb-manual', 'newplan/Master Brain & Operating Rules Manual - REFAL AI.txt', 'MB 2.1 / SOURCE-ANALYSIS 6.4', 'CY', '[]'::jsonb, 'STABLE', 'regulated', false, 'BOSS', '2026-10-07'::date, null, '2027-04-05'::date, 180, array['ar', 'en', 'el']::text[], 'pending', ''),   -- MB-F16
  ('MB-F17', 'A company ceasing activity should not assume that this removes its annual-return or financial-statement filing obligations; applicable requirements and exceptions depend on the company and period.', array['dormant-and-liquidation']::text[], 'cy-authority', 'https://www.companies.gov.cy/en/business-entities/2-company/5-lifecycle/1-running-a-company/5-guidance/filing-annual-returns-and-accounts/how-do-i-file-an-annual-return', 'Cyprus Registrar, Filing annual returns and accounts: annual return and financial statements guidance, https://www.companies.gov.cy/en/business-entities/2-company/5-lifecycle/1-running-a-company/5-guidance/filing-annual-returns-and-accounts/how-do-i-file-an-annual-return and https://www.companies.gov.cy/en/business-entities/2-company/5-lifecycle/1-running-a-company/5-guidance/filing-annual-returns-and-accounts/financial-statements-and-other-accompanying-documents (checked 2026-10-11)', 'CY', '[]'::jsonb, 'STABLE', 'regulated', false, 'BOSS', '2026-10-11'::date, null, '2027-04-09'::date, 180, array['ar', 'en', 'el']::text[], 'pending', 'Dormancy or inactivity alone should not be treated as an exemption; specific exemptions or filing treatment may apply depending on the company and reporting period. Confirm the current requirement with a Cyprus accountant. Verified against Registrar annual-return and financial-statement guidance on 2026-10-11.'),   -- MB-F17
  ('MB-F18', 'Formal strike-off is one route by which a Cyprus company may be dissolved; liquidation is not the only closure route. The appropriate process depends on the company''s circumstances.', array['dormant-and-liquidation']::text[], 'cy-authority', 'https://www.companies.gov.cy/en/business-entities/2-company/5-lifecycle/1-closing-a-company/10-guidance/voluntary-striking-off-a-company', 'Cyprus Registrar, Voluntary Striking off of company guidance, https://www.companies.gov.cy/en/business-entities/2-company/5-lifecycle/1-closing-a-company/10-guidance/voluntary-striking-off-a-company (checked 2026-10-11)', 'CY', '[]'::jsonb, 'STABLE', 'regulated', false, 'BOSS', '2026-10-11'::date, null, '2027-04-09'::date, 180, array['ar', 'en', 'el']::text[], 'pending', 'The Registrar describes voluntary striking-off as a company closure service, so liquidation is not the only route. Eligibility and consequences require case-specific review. Verified against the Registrar source on 2026-10-11.'),   -- MB-F18
  ('MB-F19', 'The headline corporate income tax rate in Cyprus is 15% from tax year 2026; the applicable tax calculation remains subject to current rules, income classification, exemptions and case facts.', array['corporate-tax']::text[], 'cy-authority', 'https://www.gov.cy/mof-tax/documents/forologiki-dilosi-eisodimatos-etaireias-t-f-4-aytoergodotoymenoy-me-elegcmenoys-logariasmoys-t-f-1/', 'Cyprus Tax Department, Company Income Tax Return (T.D.4), corporate tax rate table (15% from 2026), https://www.gov.cy/mof-tax/documents/forologiki-dilosi-eisodimatos-etaireias-t-f-4-aytoergodotoymenoy-me-elegcmenoys-logariasmoys-t-f-1/ (checked 2026-10-11); Cyprus Government, April 2026 Fiscal Report (rate applies from 1 January 2026), https://www.gov.cy/media/sites/11/2026/05/APR-2026-Final_.pdf', 'CY', '[{"value":"15%","kind":"rate"},{"value":"2026","kind":"year"}]'::jsonb, 'VOLATILE', 'regulated', true, 'BOSS', '2026-10-11'::date, '2026-01-01'::date, '2026-11-10'::date, 30, array['ar', 'en', 'el']::text[], 'pending', 'Headline rate verified against the Tax Department company return page and the government''s April 2026 report. This does not calculate liability: exemptions, income classification, special regimes, expenses and company circumstances require current tax review. The fact remains pending until independently approved.'),   -- MB-F19 [high risk]
  ('MB-F20', 'Cyprus''s IP Box regime exempts 80% of net qualifying profit calculated using the nexus fraction. Taxing the remaining 20% at the applicable headline corporate rate produces 3% arithmetic before case-specific rules; this is not a promised effective rate or a personalized tax outcome.', array['ip-box']::text[], 'cy-authority', 'https://www.gov.cy/mof/en/documents/tax-incentives/', 'Cyprus Tax Department, Tax Incentives, https://www.gov.cy/mof/en/documents/tax-incentives/ (checked 2026-10-11); 2026 base rate: MB-F19', 'CY', '[{"value":"80%","kind":"exemption"},{"value":"20%","kind":"taxable share arithmetic"},{"value":"3%","kind":"illustrative arithmetic, not promised effective rate"}]'::jsonb, 'VOLATILE', 'regulated', true, 'BOSS', '2026-10-11'::date, null, '2026-11-10'::date, 30, array['ar', 'en', 'el']::text[], 'pending', 'The 80% exemption applies to net qualifying profit using the statutory nexus fraction; it is not a flat rate. 3% is arithmetic from the 2026 base rate and is not a personalized effective rate. Current tax adviser review is required for a specific case. Verified against the Cyprus Tax Department source on 2026-10-11.'),   -- MB-F20 [high risk]
  ('MB-F21', 'The Cyprus IP Box applies only to statutory qualifying intangible assets and qualifying income calculated under the nexus approach; eligibility is not determined simply by a product description.', array['ip-box']::text[], 'cy-authority', 'https://www.gov.cy/mof/en/documents/tax-incentives/', 'Cyprus Ministry of Finance, Tax Incentives (IP Box), https://www.gov.cy/mof/en/documents/tax-incentives/ (checked 2026-10-11)', 'CY', '[]'::jsonb, 'STABLE', 'regulated', false, 'BOSS', '2026-10-11'::date, null, '2027-04-09'::date, 180, array['ar', 'en', 'el']::text[], 'pending', 'Eligibility concerns statutory qualifying intangible assets and qualifying income determined under nexus rules, not merely the product''s nature. A specialist must review the asset, rights, income and records. Verified against the Ministry of Finance source on 2026-10-11.'),   -- MB-F21
  ('MB-F22', 'The personal tax treatment of salary and dividends depends on the person''s circumstances and applicable tax rules. Tax residency and any relevant double tax treaty are factors in a case-specific analysis, not the only factors.', array['dividends-vs-salary']::text[], 'cy-authority', 'https://www.gov.cy/mof-tax/en/documents/forologiki-dilosi-eisodimatos-atomoy/', 'Cyprus Tax Department, Individual income tax return, https://www.gov.cy/mof-tax/en/documents/forologiki-dilosi-eisodimatos-atomoy/; Tax Residency/Domicility, https://www.gov.cy/mof-tax/en/documents/tax-residency-domicility/; Avoiding double taxation/Foreign tax, https://www.gov.cy/mof-tax/en/documents/avoiding-double-taxation-foreign-tax/ (checked 2026-10-11)', 'CY', '[]'::jsonb, 'STABLE', 'regulated', false, 'BOSS', '2026-10-11'::date, null, '2027-04-09'::date, 180, array['ar', 'en', 'el']::text[], 'pending', 'Personal income and dividend/special contribution treatment depends on individual circumstances and applicable rules. Tax residency, domicile and relevant treaty provisions are parts of the analysis, not a complete answer by themselves. Refer specific cases to a tax specialist. Verified against Tax Department sources on 2026-10-11.'),   -- MB-F22
  ('MB-F23', 'REFAL refuses to give a decisive personal tax opinion and converts the question into a tax advisory lead for a specialist instead.', array['corporate-tax', 'dividends-vs-salary']::text[], 'mb-manual', 'newplan/Master Brain & Operating Rules Manual - REFAL AI.txt', 'MB 2.2 / SOURCE-ANALYSIS 6.5', 'GLOBAL', '[]'::jsonb, 'STABLE', 'regulated', false, 'BOSS', '2026-10-07'::date, null, '2027-04-05'::date, 180, array['ar', 'en', 'el']::text[], 'pending', 'Override: the corporate-tax topic is VOLATILE, but this is a refusal rule carrying no figure that can go stale.'),   -- MB-F23
  ('MB-F24', 'A holding company exists to own shares in other companies, assets, property or intellectual property, while a trading company runs import, export, services or direct sales operations.', array['holding-vs-trading']::text[], 'mb-manual', 'newplan/Master Brain & Operating Rules Manual - REFAL AI.txt', 'MB 2.2 / SOURCE-ANALYSIS 6.5', 'CY', '[]'::jsonb, 'STABLE', 'explanatory', false, 'BOSS', '2026-10-07'::date, null, '2027-10-07'::date, 365, array['ar', 'en', 'el']::text[], 'pending', ''),   -- MB-F24
  ('MB-F25', 'REFAL separates the two cases by asking a holding customer how many companies or assets they own, in which countries, and whether distributions go to other entities, and by asking a trading customer about the products, the supplier, whether the customers are EU or non EU, and whether there are goods and warehouses.', array['holding-vs-trading']::text[], 'mb-manual', 'newplan/Master Brain & Operating Rules Manual - REFAL AI.txt', 'MB 2.2 / SOURCE-ANALYSIS 6.5', 'CY', '[]'::jsonb, 'STABLE', 'explanatory', false, 'BOSS', '2026-10-07'::date, null, '2027-10-07'::date, 365, array['ar', 'en', 'el']::text[], 'pending', ''),   -- MB-F25
  ('MB-F26', 'VAT registration depends on the applicable VAT rules and the company''s transactions. An EORI number identifies economic operators or other persons for customs purposes where customs identification is necessary under the applicable rules; neither registration should be assumed necessary for every trading company.', array['holding-vs-trading', 'vat-and-eori']::text[], 'cy-authority', 'https://www.mof.gov.cy/mof/customs/customs.nsf/All/B7D3EB29E4071197C22575D300335A2E', 'Cyprus Customs, Economic Operators Registration & Identification System (EORI), https://www.mof.gov.cy/mof/customs/customs.nsf/All/B7D3EB29E4071197C22575D300335A2E; Cyprus Tax Department, VAT registration FAQs, https://www.gov.cy/mof-tax/documents/eggrafi-akyrosi-f-p-a/eggrafes-mitrooy-f-p-a/sychnes-erotiseis-gia-tin-eggrafi-f-p-a/ (checked 2026-10-11)', 'CY', '[]'::jsonb, 'VOLATILE', 'regulated', false, 'BOSS', '2026-10-11'::date, null, '2026-11-10'::date, 30, array['ar', 'en', 'el']::text[], 'pending', 'Cyprus Customs describes EORI as identification for economic operators or other persons for customs purposes, used when customs code identification is necessary. VAT registration follows separate applicable rules, including rules based on taxable transactions. Check each business''s transactions and circumstances; neither requirement follows solely from the trading-company label. Verified against Cyprus Customs and Tax Department sources on 2026-10-11.'),   -- MB-F26
  ('MB-F27', 'Employment, payroll, social-insurance and third-country worker requirements depend on whether the company employs staff, the applicable procedure and the worker''s status; a holding-company label alone does not determine staffing needs.', array['holding-vs-trading', 'vat-and-eori']::text[], 'cy-authority', 'https://www.gov.cy/en/service/employers-platform/', 'Republic of Cyprus, Employers Platform, https://www.gov.cy/en/service/employers-platform/; Application for employment of third-country nationals, https://www.gov.cy/en/service/application-for-employment-of-third-country-nationals/ (checked 2026-10-11)', 'CY', '[]'::jsonb, 'VOLATILE', 'regulated', false, 'BOSS', '2026-10-11'::date, null, '2026-11-10'::date, 30, array['ar', 'en', 'el']::text[], 'pending', 'The cited government portals identify employer processes and third-country employment applications; they do not support a general claim about how holding companies are usually staffed. Requirements depend on the procedure and worker status. Verify current requirements for each case. Checked 2026-10-11.'),   -- MB-F27
  ('MB-F28', 'REFAL never gives a definitive promise about opening a bank account or activating a payment gateway such as Stripe, PayPal, Amazon or Shopify. She says honestly that nobody can promise another institution''s approval, and pivots to building a clean file from day one.', array['banking-and-payment-gateways']::text[], 'mb-manual', 'newplan/Master Brain & Operating Rules Manual - REFAL AI.txt', 'MB 2.3 / SOURCE-ANALYSIS 6.6', 'GLOBAL', '[]'::jsonb, 'STABLE', 'regulated', false, 'BOSS', '2026-10-07'::date, null, '2027-04-05'::date, 180, array['ar', 'en', 'el']::text[], 'pending', 'The golden banking rule, and the template for every can you guarantee X answer.'),   -- MB-F28
  ('MB-F29', 'The final decision on a bank account or a payment gateway belongs to the financial institution''s own risk assessment and its KYC and AML compliance requirements.', array['banking-and-payment-gateways']::text[], 'mb-manual', 'newplan/Master Brain & Operating Rules Manual - REFAL AI.txt', 'MB 2.3 / SOURCE-ANALYSIS 6.6', 'GLOBAL', '[]'::jsonb, 'STABLE', 'regulated', false, 'BOSS', '2026-10-07'::date, null, '2027-04-05'::date, 180, array['ar', 'en', 'el']::text[], 'pending', ''),   -- MB-F29
  ('MB-F30', 'The Cyprus investor immigration permit route for eligible third-country nationals includes a qualifying investment of at least €300,000, plus VAT where applicable, and other programme criteria; this is not a rule for every permanent-residence route.', array['permanent-residency']::text[], 'cy-authority', 'https://www.gov.cy/mip-md/en/documents/companies-investors-permanent-residence-3/immigration-permits-for-investors/', 'Cyprus Migration Department, Immigration Permits for Investors, https://www.gov.cy/mip-md/en/documents/companies-investors-permanent-residence-3/immigration-permits-for-investors/ (checked 2026-10-11)', 'CY', '[{"value":"€300,000 plus VAT","kind":"amount"}]'::jsonb, 'VOLATILE', 'regulated', true, 'BOSS', '2026-10-11'::date, null, '2026-11-10'::date, 30, array['ar', 'en', 'el']::text[], 'pending', 'Scope is the named investor immigration permit route for eligible third-country nationals and its additional conditions. It does not describe every permanent-residence route. Verify current criteria with the Migration Department or an immigration specialist.'),   -- MB-F30 [high risk]
  ('MB-F31', 'Under the Cyprus investor immigration permit route, the main applicant must evidence annual secure income of at least €50,000, with the required source and proof assessed under the programme; this is not a universal permanent-residence requirement.', array['permanent-residency']::text[], 'cy-authority', 'https://www.gov.cy/mip-md/en/documents/companies-investors-permanent-residence-3/immigration-permits-for-investors/', 'Cyprus Migration Department, Immigration Permits for Investors, income requirement and proof/source criteria, https://www.gov.cy/mip-md/en/documents/companies-investors-permanent-residence-3/immigration-permits-for-investors/ (checked 2026-10-11)', 'CY', '[{"value":"€50,000","kind":"amount"}]'::jsonb, 'VOLATILE', 'regulated', true, 'BOSS', '2026-10-11'::date, null, '2026-11-10'::date, 30, array['ar', 'en', 'el']::text[], 'pending', 'Applies to the named investor permit route. Income amount, security, source and supporting evidence must be checked against current programme criteria and the applicant''s circumstances; not a universal rule for all permanent-residence applications.'),   -- MB-F31 [high risk]
  ('MB-F32', 'Under the Cyprus investor immigration permit route, the annual secure-income requirement increases by €15,000 for a spouse, subject to the programme''s current evidence and other criteria; this is not a universal permanent-residence rule.', array['permanent-residency']::text[], 'cy-authority', 'https://www.gov.cy/mip-md/en/documents/companies-investors-permanent-residence-3/immigration-permits-for-investors/', 'Cyprus Migration Department, Immigration Permits for Investors, annual income requirement, https://www.gov.cy/mip-md/en/documents/companies-investors-permanent-residence-3/immigration-permits-for-investors/ (checked 2026-10-11)', 'CY', '[{"value":"€15,000","kind":"amount"}]'::jsonb, 'VOLATILE', 'regulated', true, 'BOSS', '2026-10-11'::date, null, '2026-11-10'::date, 30, array['ar', 'en', 'el']::text[], 'pending', 'The increment is specific to the investor permit policy and its income evidence criteria, not a universal permanent-residence requirement. Verify the current policy and case facts.'),   -- MB-F32 [high risk]
  ('MB-F33', 'Under the Cyprus investor immigration permit route, the annual secure-income requirement increases by €10,000 for each dependent minor child, subject to the programme''s current evidence and other criteria; this is not a universal permanent-residence rule.', array['permanent-residency']::text[], 'cy-authority', 'https://www.gov.cy/mip-md/en/documents/companies-investors-permanent-residence-3/immigration-permits-for-investors/', 'Cyprus Migration Department, Immigration Permits for Investors, annual income requirement, https://www.gov.cy/mip-md/en/documents/companies-investors-permanent-residence-3/immigration-permits-for-investors/ (checked 2026-10-11)', 'CY', '[{"value":"€10,000","kind":"amount"}]'::jsonb, 'VOLATILE', 'regulated', true, 'BOSS', '2026-10-11'::date, null, '2026-11-10'::date, 30, array['ar', 'en', 'el']::text[], 'pending', 'The increment is specific to the investor permit policy and its income evidence criteria, not a universal permanent-residence requirement. Verify the current policy and case facts.'),   -- MB-F33 [high risk]
  ('MB-F34', 'An individual who qualifies as non-domiciled under Cyprus rules is generally outside Special Defence Contribution on dividends and interest while eligible. Cyprus applies a deemed-domicile test after 17 of the previous 20 years of tax residence, and the 2026 rules provide an alternative extension application subject to its conditions; personal eligibility and tax treatment require current specialist review.', array['non-dom-status']::text[], 'cy-authority', 'newplan/Master Brain & Operating Rules Manual - REFAL AI.txt', 'Cyprus Tax Department: https://www.gov.cy/mof-tax/en/documents/tax-residency-domicility/; alternative SDC extension: https://www.gov.cy/mof-tfa/en/documents/application-for-the-alternative-method-of-imposing-the-special-contribution-for-the-defence/', 'CY', '[{"value":"0%","kind":"rate"},{"value":"17 years","kind":"duration"},{"value":"20 years","kind":"duration"}]'::jsonb, 'VOLATILE', 'regulated', true, 'BOSS', '2026-10-07'::date, null, '2026-11-06'::date, 30, array['ar', 'en', 'el']::text[], 'pending', 'Verified against Cyprus Tax Department residency/domicility guidance and the alternative SDC extension application page on 2026-10-11. Do not summarize as a universal 0% rate lasting exactly 17 years.'),   -- MB-F34 [high risk]
  ('MB-F35', 'Source of Funds is the direct path of the money used in this specific transaction, for example a transfer from a named personal bank account or the sale of a specific property.', array['source-of-funds-vs-wealth']::text[], 'mb-manual', 'newplan/Master Brain & Operating Rules Manual - REFAL AI.txt', 'MB 2.4 / SOURCE-ANALYSIS 6.7', 'GLOBAL', '[]'::jsonb, 'STABLE', 'regulated', false, 'BOSS', '2026-10-07'::date, null, '2027-04-05'::date, 180, array['ar', 'en', 'el']::text[], 'pending', ''),   -- MB-F35
  ('MB-F36', 'Source of Wealth is the cumulative history of how the customer''s wealth was built over the years, such as business profits, inheritance or earlier investments.', array['source-of-funds-vs-wealth']::text[], 'mb-manual', 'newplan/Master Brain & Operating Rules Manual - REFAL AI.txt', 'MB 2.4 / SOURCE-ANALYSIS 6.7', 'GLOBAL', '[]'::jsonb, 'STABLE', 'regulated', false, 'BOSS', '2026-10-07'::date, null, '2027-04-05'::date, 180, array['ar', 'en', 'el']::text[], 'pending', ''),   -- MB-F36
  ('MB-F37', 'REFAL explains comfortably and without interrogating the customer that banks and immigration authorities require documentation of the Source of Funds for the deal, and in some cases the general Source of Wealth, as a normal standard compliance step.', array['source-of-funds-vs-wealth']::text[], 'mb-manual', 'newplan/Master Brain & Operating Rules Manual - REFAL AI.txt', 'MB 2.4 / SOURCE-ANALYSIS 6.7', 'GLOBAL', '[]'::jsonb, 'STABLE', 'regulated', false, 'BOSS', '2026-10-07'::date, null, '2027-04-05'::date, 180, array['ar', 'en', 'el']::text[], 'pending', ''),   -- MB-F37
  ('MB-F38', 'Under the Cyprus investor immigration permit policy for eligible third-country nationals, Category A requires a first sale of a house or apartment from a development company for at least €300,000 plus VAT, subject to the other policy conditions.', array['permanent-residency']::text[], 'cy-authority', 'newplan/Master Brain & Operating Rules Manual - REFAL AI.txt', 'MB 2.4 / SOURCE-ANALYSIS 6.7', 'CY', '[{"value":"€300,000 plus VAT","kind":"amount"}]'::jsonb, 'VOLATILE', 'regulated', true, 'BOSS', '2026-10-07'::date, null, '2026-11-06'::date, 30, array['ar', 'en', 'el']::text[], 'pending', 'The first-sale condition is mandatory, not preferred. Verified against the Migration Department investor permit criteria on 2026-10-11.'),   -- MB-F38 [high risk]
  ('MB-F39', 'Under the Cyprus investor immigration permit policy for eligible third-country nationals, Category B covers other qualifying property types such as offices, shops or hotels with an investment of at least €300,000, subject to the policy conditions.', array['permanent-residency']::text[], 'cy-authority', 'newplan/Master Brain & Operating Rules Manual - REFAL AI.txt', 'MB 2.4 / SOURCE-ANALYSIS 6.7', 'CY', '[{"value":"€300,000","kind":"amount"}]'::jsonb, 'VOLATILE', 'regulated', true, 'BOSS', '2026-10-07'::date, null, '2026-11-06'::date, 30, array['ar', 'en', 'el']::text[], 'pending', ''),   -- MB-F39 [high risk]
  ('MB-F40', 'Under Category C of the Cyprus investor immigration permit route, the investment is at least €300,000 in the share capital of a Cyprus company, subject to the operating-company, physical-presence, at-least-five-employees and other policy conditions.', array['permanent-residency']::text[], 'cy-authority', 'https://www.gov.cy/mip-md/en/documents/companies-investors-permanent-residence-3/immigration-permits-for-investors/', 'Cyprus Migration Department, Immigration Permits for Investors, Category C conditions, https://www.gov.cy/mip-md/en/documents/companies-investors-permanent-residence-3/immigration-permits-for-investors/ (checked 2026-10-11)', 'CY', '[{"value":"€300,000","kind":"amount"}]'::jsonb, 'VOLATILE', 'regulated', true, 'BOSS', '2026-10-11'::date, null, '2026-11-10'::date, 30, array['ar', 'en', 'el']::text[], 'pending', 'Retain all policy conditions, including operating-company requirements, actual physical presence, minimum staffing and any other criteria. Confirm current policy before advising.'),   -- MB-F40 [high risk]
  ('MB-F41', 'Under Category D of the Cyprus investor immigration permit route, an investment of at least €300,000 may be made in qualifying Cyprus investment-fund units that meet the programme''s conditions and are held in Cyprus.', array['permanent-residency']::text[], 'cy-authority', 'https://www.gov.cy/mip-md/en/documents/companies-investors-permanent-residence-3/immigration-permits-for-investors/', 'Cyprus Migration Department, Immigration Permits for Investors, Category D conditions, https://www.gov.cy/mip-md/en/documents/companies-investors-permanent-residence-3/immigration-permits-for-investors/ (checked 2026-10-11)', 'CY', '[{"value":"€300,000","kind":"amount"}]'::jsonb, 'VOLATILE', 'regulated', true, 'BOSS', '2026-10-11'::date, null, '2026-11-10'::date, 30, array['ar', 'en', 'el']::text[], 'pending', 'The fund units must satisfy current programme conditions and be held in Cyprus. Confirm eligibility of the fund and investment with an immigration specialist.'),   -- MB-F41 [high risk]
  ('MB-F42', 'For a relocating family REFAL distinguishes public, private and international schools with British or English curricula, and asks the children''s ages so the right schools and areas can be shortlisted.', array['relocation-checklist']::text[], 'mb-manual', 'newplan/Master Brain & Operating Rules Manual - REFAL AI.txt', 'MB 2.4 / SOURCE-ANALYSIS 6.7', 'CY', '[]'::jsonb, 'STABLE', 'explanatory', false, 'BOSS', '2026-10-07'::date, null, '2027-10-07'::date, 365, array['ar', 'en', 'el']::text[], 'pending', ''),   -- MB-F42
  ('MB-F43', 'Access to Cyprus''s GESY depends on the person''s beneficiary eligibility and registration requirements. The cited guidance does not establish that private health insurance can simply be added on top; confirm coverage separately with the insurer and a qualified adviser.', array['relocation-checklist']::text[], 'cy-authority', 'https://www.gesy.org.cy/sites/Sites?d=Desktop&locale=en_US&lookuphost=%2Fen-us%2F&lookuppage=hiobeneficiaryeligiblility', 'Health Insurance Organisation, GHS Beneficiary Categories and Enrolment Process, https://www.gesy.org.cy/sites/Sites?d=Desktop&locale=en_US&lookuphost=%2Fen-us%2F&lookuppage=hiobeneficiaryeligiblility and https://www.gesy.org.cy/sites/Sites?d=Desktop&locale=en_US&lookuphost=%2Fen-us%2F&lookuppage=hiobeneficiaryenrollmentpro (checked 2026-10-11)', 'CY', '[]'::jsonb, 'STABLE', 'explanatory', false, 'BOSS', '2026-10-11'::date, null, '2027-10-11'::date, 365, array['ar', 'en', 'el']::text[], 'pending', 'The Health Insurance Organisation lists beneficiary categories and requires registration in the Beneficiary Registry and a personal-doctor list for access to services. The cited sources do not establish that private insurance can simply be added on top; check any private policy separately. Verified against HIO guidance on 2026-10-11.'),   -- MB-F43
  ('MB-F44', 'Housing, transport and car purchase costs in Cyprus are variable, so REFAL gives no generic numbers and instead requires a fresh current estimate based on the city and the family size.', array['relocation-checklist']::text[], 'mb-manual', 'newplan/Master Brain & Operating Rules Manual - REFAL AI.txt', 'MB 2.4 / SOURCE-ANALYSIS 6.7', 'CY', '[]'::jsonb, 'STABLE', 'explanatory', false, 'BOSS', '2026-10-11'::date, null, '2027-10-11'::date, 365, array['ar', 'en', 'el']::text[], 'pending', 'Eligibility categories and beneficiary registration are required for access to GESY services. These sources do not establish that private insurance can simply be added on top; describe private cover only after checking the relevant policy and provider.'),   -- MB-F44
  ('MB-F45', 'The Cyprus property buyer journey runs through search, selection, reservation deposit, legal due diligence, contract, payment plan, tax and VAT, transfer and registration, delivery, then ongoing management.', array['property-buyer-journey']::text[], 'mb-manual', 'newplan/Master Brain & Operating Rules Manual - REFAL AI.txt', 'MB 2.5 / SOURCE-ANALYSIS 6.8', 'CY', '[]'::jsonb, 'STABLE', 'explanatory', false, 'BOSS', '2026-10-07'::date, null, '2027-10-07'::date, 365, array['ar', 'en', 'el']::text[], 'pending', ''),   -- MB-F45
  ('MB-F46', 'A completed property suits a buyer who wants a home to move into or a fast rental yield.', array['offplan-vs-completed']::text[], 'mb-manual', 'newplan/Master Brain & Operating Rules Manual - REFAL AI.txt', 'MB 2.5 / SOURCE-ANALYSIS 6.8', 'CY', '[]'::jsonb, 'STABLE', 'explanatory', false, 'BOSS', '2026-10-07'::date, null, '2027-10-07'::date, 365, array['ar', 'en', 'el']::text[], 'pending', ''),   -- MB-F46
  ('MB-F47', 'An off plan property suits a buyer who needs an easier payment plan and can accept a future delivery date.', array['offplan-vs-completed']::text[], 'mb-manual', 'newplan/Master Brain & Operating Rules Manual - REFAL AI.txt', 'MB 2.5 / SOURCE-ANALYSIS 6.8', 'CY', '[]'::jsonb, 'STABLE', 'explanatory', false, 'BOSS', '2026-10-07'::date, null, '2027-10-07'::date, 365, array['ar', 'en', 'el']::text[], 'pending', ''),   -- MB-F47
  ('MB-F48', 'Cyprus''s standard VAT rate is 19%. A 5% reduced rate may apply to a qualifying purchase or construction of a primary residence only when statutory conditions and residence-use obligations are met; eligibility is case-specific.', array['property-vat']::text[], 'cy-authority', 'https://www.gov.cy/mof-tax/documents/meiomenos-syntelestis-f-p-a-5/sychnes-erotiseis-gia-ton-meiomeno-syntelesti-f-p-a-5/', 'Cyprus Tax Department, Reduced 5% VAT FAQ and VAT rates, https://www.gov.cy/mof-tax/documents/meiomenos-syntelestis-f-p-a-5/sychnes-erotiseis-gia-ton-meiomeno-syntelesti-f-p-a-5/ and https://www.gov.cy/mof-tax/documents/syntelestes-f-p-a/ (checked 2026-10-11)', 'CY', '[{"value":"19%","kind":"rate"},{"value":"5%","kind":"rate"}]'::jsonb, 'VOLATILE', 'regulated', true, 'BOSS', '2026-10-11'::date, null, '2026-11-10'::date, 30, array['ar', 'en', 'el']::text[], 'pending', 'The reduced rate is limited to qualifying primary-residence purchase/construction under statutory conditions and ongoing residence-use obligations. It is not a general personal-use rate. Confirm the current law and facts for the specific property and buyer.'),   -- MB-F48 [high risk]
  ('MB-F49', 'Property VAT is calculated precisely by the team for the specific case, and REFAL avoids giving loose generic numbers.', array['property-vat']::text[], 'mb-manual', 'newplan/Master Brain & Operating Rules Manual - REFAL AI.txt', 'MB 2.5 / SOURCE-ANALYSIS 6.8', 'CY', '[]'::jsonb, 'STABLE', 'regulated', false, 'BOSS', '2026-10-07'::date, null, '2027-04-05'::date, 180, array['ar', 'en', 'el']::text[], 'pending', 'Override: topic is VOLATILE, but this is a refusal rule with no rate of its own to expire.'),   -- MB-F49
  ('MB-F50', 'REFAL is categorically forbidden from guessing or stating a fixed reservation deposit amount. The terms and the value differ per project and per property and are called dynamically from the live property database.', array['property-buyer-journey']::text[], 'mb-manual', 'newplan/Master Brain & Operating Rules Manual - REFAL AI.txt', 'MB 2.5 / SOURCE-ANALYSIS 6.8', 'CY', '[]'::jsonb, 'STABLE', 'commercial', false, 'BOSS', '2026-10-07'::date, null, '2027-10-07'::date, 365, array['ar', 'en', 'el']::text[], 'pending', 'Override: topic is explanatory, but this rule guards a price figure, so a breach is a mis-quoted commercial term.'),   -- MB-F50
  ('MB-F51', 'Limassol is the international business hub, coastal and luxury, the most expensive city in Cyprus, and it suits capital growth, luxury investment, high net worth investors and international corporate activity.', array['cyprus-cities']::text[], 'mb-manual', 'newplan/Master Brain & Operating Rules Manual - REFAL AI.txt', 'MB 2.5 / SOURCE-ANALYSIS 6.8', 'CY', '[]'::jsonb, 'STABLE', 'explanatory', false, 'BOSS', '2026-10-07'::date, null, '2027-10-07'::date, 365, array['ar', 'en', 'el']::text[], 'pending', ''),   -- MB-F51
  ('MB-F52', 'Larnaca is a fast growing coastal city close to the airport with medium and rising prices, strong rental yields and major infrastructure development plans, and it suits investors seeking growth opportunities.', array['cyprus-cities']::text[], 'mb-manual', 'newplan/Master Brain & Operating Rules Manual - REFAL AI.txt', 'MB 2.5 / SOURCE-ANALYSIS 6.8', 'CY', '[]'::jsonb, 'STABLE', 'explanatory', false, 'BOSS', '2026-10-07'::date, null, '2027-10-07'::date, 365, array['ar', 'en', 'el']::text[], 'pending', ''),   -- MB-F52
  ('MB-F53', 'Paphos is a quiet lifestyle and tourism city at medium prices, suiting international buyers, holiday homes, short and long term rentals and family living.', array['cyprus-cities']::text[], 'mb-manual', 'newplan/Master Brain & Operating Rules Manual - REFAL AI.txt', 'MB 2.5 / SOURCE-ANALYSIS 6.8', 'CY', '[]'::jsonb, 'STABLE', 'explanatory', false, 'BOSS', '2026-10-07'::date, null, '2027-10-07'::date, 365, array['ar', 'en', 'el']::text[], 'pending', ''),   -- MB-F53
  ('MB-F54', 'Nicosia is the capital and the administrative, governmental and university centre, with stable prices built on local demand and very stable long term rentals to students, corporate and institutional staff.', array['cyprus-cities']::text[], 'mb-manual', 'newplan/Master Brain & Operating Rules Manual - REFAL AI.txt', 'MB 2.5 / SOURCE-ANALYSIS 6.8', 'CY', '[]'::jsonb, 'STABLE', 'explanatory', false, 'BOSS', '2026-10-07'::date, null, '2027-10-07'::date, 365, array['ar', 'en', 'el']::text[], 'pending', ''),   -- MB-F54
  ('MB-F55', 'REFAL refuses to quote a return percentage to please the customer. She explains that the return depends on the project, the price, the expected rent and the costs, asks for the budget and the area so it can be computed on real figures, states plainly that nobody can guarantee a future property price, and redirects to choosing a property with strong fundamentals in an in demand location.', array['cyprus-cities']::text[], 'mb-manual', 'newplan/Master Brain & Operating Rules Manual - REFAL AI.txt', 'MB 2.5 / SOURCE-ANALYSIS 6.8', 'CY', '[]'::jsonb, 'STABLE', 'explanatory', false, 'BOSS', '2026-10-07'::date, null, '2027-10-07'::date, 365, array['ar', 'en', 'el']::text[], 'pending', ''),   -- MB-F55
  ('MB-F56', 'Landowner partnership deals and major construction tenders involve assets worth millions, so REFAL performs rapid silent filtering instead of treating them as an ordinary property enquiry.', array['landowners-and-construction']::text[], 'mb-manual', 'newplan/Master Brain & Operating Rules Manual - REFAL AI.txt', 'MB 2.6 / SOURCE-ANALYSIS 6.9', 'CY', '[]'::jsonb, 'STABLE', 'regulated', false, 'BOSS', '2026-10-07'::date, null, '2027-04-05'::date, 180, array['ar', 'en', 'el']::text[], 'pending', 'Worth millions is an order of magnitude in the manual, not a stated figure, so no number entry.'),   -- MB-F56
  ('MB-F57', 'A landowner joint venture opportunity is signalled when the customer says they own land in Cyprus and want to develop it or partner with a developer.', array['landowners-and-construction']::text[], 'mb-manual', 'newplan/Master Brain & Operating Rules Manual - REFAL AI.txt', 'MB 2.6 / SOURCE-ANALYSIS 6.9', 'CY', '[]'::jsonb, 'STABLE', 'regulated', false, 'BOSS', '2026-10-07'::date, null, '2027-04-05'::date, 180, array['ar', 'en', 'el']::text[], 'pending', ''),   -- MB-F57
  ('MB-F58', 'On a landowner joint venture REFAL asks for the land location, the area, the building density, and whether preliminary permits already exist.', array['landowners-and-construction']::text[], 'mb-manual', 'newplan/Master Brain & Operating Rules Manual - REFAL AI.txt', 'MB 2.6 / SOURCE-ANALYSIS 6.9', 'CY', '[]'::jsonb, 'STABLE', 'regulated', false, 'BOSS', '2026-10-07'::date, null, '2027-04-05'::date, 180, array['ar', 'en', 'el']::text[], 'pending', ''),   -- MB-F58
  ('MB-F59', 'Because a land development opportunity is not an ordinary property purchase, REFAL states that the file requires direct review by the development and investment team and escalates it there.', array['landowners-and-construction']::text[], 'mb-manual', 'newplan/Master Brain & Operating Rules Manual - REFAL AI.txt', 'MB 2.6 / SOURCE-ANALYSIS 6.9', 'CY', '[]'::jsonb, 'STABLE', 'regulated', false, 'BOSS', '2026-10-07'::date, null, '2027-04-05'::date, 180, array['ar', 'en', 'el']::text[], 'pending', ''),   -- MB-F59
  ('MB-F60', 'A construction tender opportunity is signalled when the customer says they need a contractor for a large project or that they have a construction tender.', array['landowners-and-construction']::text[], 'mb-manual', 'newplan/Master Brain & Operating Rules Manual - REFAL AI.txt', 'MB 2.6 / SOURCE-ANALYSIS 6.9', 'CY', '[]'::jsonb, 'STABLE', 'regulated', false, 'BOSS', '2026-10-07'::date, null, '2027-04-05'::date, 180, array['ar', 'en', 'el']::text[], 'pending', ''),   -- MB-F60
  ('MB-F61', 'On a construction tender REFAL asks for the project size, the location, whether engineering plans such as a BOQ or architectural drawings exist, and the planned start timeline.', array['landowners-and-construction']::text[], 'mb-manual', 'newplan/Master Brain & Operating Rules Manual - REFAL AI.txt', 'MB 2.6 / SOURCE-ANALYSIS 6.9', 'CY', '[]'::jsonb, 'STABLE', 'regulated', false, 'BOSS', '2026-10-07'::date, null, '2027-04-05'::date, 180, array['ar', 'en', 'el']::text[], 'pending', ''),   -- MB-F61
  ('MB-F62', 'REFAL raises an urgent executive summary of a construction tender to the group''s construction sector and gives no prices and no preliminary estimates of her own at all.', array['landowners-and-construction']::text[], 'mb-manual', 'newplan/Master Brain & Operating Rules Manual - REFAL AI.txt', 'MB 2.6 / SOURCE-ANALYSIS 6.9', 'CY', '[]'::jsonb, 'STABLE', 'regulated', false, 'BOSS', '2026-10-07'::date, null, '2027-04-05'::date, 180, array['ar', 'en', 'el']::text[], 'pending', ''),   -- MB-F62
  ('MB-F63', 'Refalco registers trademarks in Cyprus and across the European Union.', array['legal-ip-contracts']::text[], 'mb-manual', 'newplan/Master Brain & Operating Rules Manual - REFAL AI.txt', 'MB 2.6 / SOURCE-ANALYSIS 6.9', 'EU', '[]'::jsonb, 'STABLE', 'regulated', false, 'BOSS', '2026-10-07'::date, null, '2027-04-05'::date, 180, array['ar', 'en', 'el']::text[], 'pending', ''),   -- MB-F63
  ('MB-F64', 'Refalco drafts Shareholders Agreements, the governance agreements between owners and partners that prevent future disputes.', array['legal-ip-contracts']::text[], 'mb-manual', 'newplan/Master Brain & Operating Rules Manual - REFAL AI.txt', 'MB 2.6 / SOURCE-ANALYSIS 6.9', 'CY', '[]'::jsonb, 'STABLE', 'regulated', false, 'BOSS', '2026-10-07'::date, null, '2027-04-05'::date, 180, array['ar', 'en', 'el']::text[], 'pending', ''),   -- MB-F64
  ('MB-F65', 'Refalco drafts service and employment agreements, covering service provision, development work and employee contracts.', array['legal-ip-contracts']::text[], 'mb-manual', 'newplan/Master Brain & Operating Rules Manual - REFAL AI.txt', 'MB 2.6 / SOURCE-ANALYSIS 6.9', 'CY', '[]'::jsonb, 'STABLE', 'regulated', false, 'BOSS', '2026-10-07'::date, null, '2027-04-05'::date, 180, array['ar', 'en', 'el']::text[], 'pending', ''),   -- MB-F65
  ('MB-F66', 'Refalco advises on website terms and conditions and on European data protection compliance under GDPR.', array['legal-ip-contracts']::text[], 'mb-manual', 'newplan/Master Brain & Operating Rules Manual - REFAL AI.txt', 'MB 2.6 / SOURCE-ANALYSIS 6.9', 'EU', '[]'::jsonb, 'STABLE', 'regulated', false, 'BOSS', '2026-10-07'::date, null, '2027-04-05'::date, 180, array['ar', 'en', 'el']::text[], 'pending', ''),   -- MB-F66
  ('MB-C1', 'Refalco has operational roots in Cyprus going back to the year 2000.', array['company-profile']::text[], 'refalco-commercial', 'newplan/Master Brain & Operating Rules Manual - REFAL AI.txt', 'MB 2.0, 3.0 / SOURCE-ANALYSIS 6.1', 'CY', '[{"value":"2000","kind":"year"}]'::jsonb, 'VOLATILE', 'commercial', true, 'BOSS', '2026-10-07'::date, null, '2026-11-06'::date, 30, array['ar', 'en', 'el']::text[], 'pending', ''),   -- MB-C1 [high risk]
