-- Re-running this file refreshes the catalogue-owned fields and leaves the
-- operator-managed evidence and review fields alone, so a second run can never un-expire a fact
-- someone retired or revive one they blocked.
on conflict (fact_id) do update set
  claim_text = excluded.claim_text,
  topics = excluded.topics,
  source_type = excluded.source_type,
  jurisdiction = excluded.jurisdiction,
  numbers = excluded.numbers,
  volatility = excluded.volatility,
  trust_tier = excluded.trust_tier,
  high_risk = excluded.high_risk;
  -- status, reviewer, verified_at, effective_from, expiry_or_review_at,
  -- source_url_or_document, source_ref, notes, review_cadence_days and
  -- approved_languages are intentionally untouched.

insert into public.refal_fact_register_audit (fact_id, action, actor, previous, next, reason)
select fact_id, 'seed', 'BOSS', '{}'::jsonb,
       jsonb_build_object('status', status, 'verified_at', verified_at, 'expiry_or_review_at', expiry_or_review_at),
       'Candidate extracted from the Master Brain; approval remains pending'
from public.refal_fact_register r
where not exists (
  select 1 from public.refal_fact_register_audit a where a.fact_id = r.fact_id and a.action = 'seed'
);

